def seed_stores_and_action_configs(apps, schema_editor):
    """Idempotently seed the two stores (+ zero-balance accounts) and action configs.

    Formal NPCs are created by the ``seed_village_v1`` management command, not by
    migrations.  ``10014`` exists via an inventory migration, but ``10015`` does
    not, so ``get_or_create`` the operator to guarantee both stores seed
    consistently regardless of seed-command ordering.
    """
    NpcDefinition = apps.get_model("inventory", "NpcDefinition")
    VillageStore = apps.get_model("village", "VillageStore")
    VillageStoreAccount = apps.get_model("village", "VillageStoreAccount")
    VillageActionDurationConfig = apps.get_model("village", "VillageActionDurationConfig")

    for seed in STORE_SEEDS:
        operator, _ = NpcDefinition.objects.get_or_create(
            agent_id=seed["operator_agent_id"],
            defaults={"name": seed["operator_name"], "is_test_only": False},
        )
        store, _ = VillageStore.objects.get_or_create(
            store_code=seed["store_code"],
            defaults={
                "location_code": seed["location_code"],
                "operator_npc": operator,
                "display_name": seed["display_name"],
                "status": "OPEN",
                "transaction_fee_bps": 500,
                "minimum_fee": 1,
                "inventory_version": 0,
            },
        )
        VillageStoreAccount.objects.get_or_create(
            store=store,
            defaults={"balance": 0, "account_version": 0},
        )

    for action_name, duration_minutes in NEW_ACTION_DURATIONS.items():
        VillageActionDurationConfig.objects.get_or_create(
            action_name=action_name,
            defaults={"duration_minutes": duration_minutes},
        )


def reverse_stores_and_action_configs(apps, schema_editor):
    VillageStore = apps.get_model("village", "VillageStore")
    VillageActionDurationConfig = apps.get_model("village", "VillageActionDurationConfig")

    VillageStore.objects.filter(
        store_code__in=[seed["store_code"] for seed in STORE_SEEDS]
    ).delete()
    VillageActionDurationConfig.objects.filter(
        action_name__in=list(NEW_ACTION_DURATIONS.keys())
    ).delete()


